state = {'n': 0}

def call():
    state['n'] += 1
    if state['n'] < 3:
        raise ConnectionError('temporary')
    return 'ok'

def retry(fn, attempts):
    last = None
    for _ in range(attempts):
        try:
            return fn()
        except ConnectionError as e:
            last = e
    raise last

print('result:', retry(call, 5))
print('calls:', state['n'])

