lines = ['1,5', '2,x', '3,12', '4,', '5,8', '6,20']
skipped = 0

def parse(it):
    global skipped
    for line in it:
        i, v = line.split(',')
        try:
            yield int(i), int(v)
        except ValueError:
            skipped += 1

def big(it):
    return (r for r in it if r[1] >= 8)

def batches(it, n):
    batch = []
    for r in it:
        batch.append(r[0])
        if len(batch) == n:
            yield batch
            batch = []
    if batch:
        yield batch

for b in batches(big(parse(lines)), 2):
    print(b)
print('skipped:', skipped)
